<section class="panel"><h2>Protected activity history</h2><p class="muted">Financial postings, configuration changes and access events. Audit entries cannot be edited through the application.</p><div class="table-wrap"><table><thead><tr><th>Date / time</th><th>User</th><th>Action</th><th>Record</th><th>Description</th><th>IP address</th></tr></thead><tbody><?php if(!$rows) emptyRow(6); foreach(array_slice($rows,0,100) as $r): ?><tr><td><?= e($r['created_at']) ?></td><td><?= e($r['user_name']??'System') ?></td><td><?= e($r['action']) ?></td><td><?= e($r['entity'].' #'.$r['record_id']) ?></td><td><?= e($r['description']) ?></td><td><?= e($r['ip_address']) ?></td></tr><?php endforeach ?></tbody></table></div><?php pagination(max(1,(int)($_GET['p']??1)),count($rows)>100); ?></section>
